#include <bits/stdc++.h>
using namespace std;

vector<long long> polynomialMultiply(const vector<long long>& p1, const vector<long long>& p2, long long mod) {
    int n1 = p1.size(), n2 = p2.size();
    int size = 1 << (32 - __builtin_clz(n1 + n2 - 1));
    size = max(size, 2);
    vector<double> aReal(size, 0), aImag(size, 0);
    for (int i = 0; i < n1; i++) {
        long long x = ((p1[i] % mod) + mod) % mod;
        aReal[i] = (double)(x & ((1 << 15) - 1));
        aImag[i] = (double)(x >> 15);
    }
    fftTransform(aReal, aImag, false);
    vector<double> bReal(size, 0), bImag(size, 0);
    if (&p1 == &p2) {
        for (int i = 0; i < size; i++) {
            bReal[i] = aReal[i];
            bImag[i] = aImag[i];
        }
    } else {
        for (int i = 0; i < n2; i++) {
            long long x = ((p2[i] % mod) + mod) % mod;
            bReal[i] = (double)(x & ((1 << 15) - 1));
            bImag[i] = (double)(x >> 15);
        }
        fftTransform(bReal, bImag, false);
    }

    vector<double> faReal(size, 0), faImag(size, 0);
    vector<double> fbReal(size, 0), fbImag(size, 0);
    double cof = 0.25 / size;
    for (int i = 0; i < size; i++) {
        int j = (size - i) & (size - 1);
        double a1r = aReal[i] + aReal[j];
        double a1i = aImag[i] - aImag[j];
        double a2r = aImag[i] + aImag[j];
        double a2i = aReal[j] - aReal[i];

        double b1r = (bReal[i] + bReal[j]) * cof;
        double b1i = (bImag[i] - bImag[j]) * cof;
        double b2r = (bImag[i] + bImag[j]) * cof;
        double b2i = (bReal[j] - bReal[i]) * cof;

        faReal[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
        faImag[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;

        fbReal[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
        fbImag[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
    }

    fftTransform(faReal, faImag, true);
    fftTransform(fbReal, fbImag, true);

    vector<long long> res(size, 0);
    for (int i = 0; i < size; i++) {
        long long aa = (long long)round(faReal[i]);
        long long bb = (long long)round(fbReal[i]);
        long long cc = (long long)round(faImag[i]);
        res[i] = (aa + ((bb % mod) << 15) + ((cc % mod) << 30)) % mod;
    }
    return res;
}

void fftTransform(vector<double>& real, vector<double>& imag, bool invert) {
    int n = real.size();
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; (j & bit) != 0; bit >>= 1) {
            j &= ~bit;
        }
        j |= bit;
        if (i < j) {
            swap(real[i], real[j]);
            swap(imag[i], imag[j]);
        }
    }
    for (int len = 2; len <= n; len <<= 1) {
        double angle = 2 * M_PI / len * (invert ? -1 : 1);
        double wlenCos = cos(angle);
        double wlenSin = sin(angle);
        for (int i = 0; i < n; i += len) {
            double wCos = 1, wSin = 0;
            for (int j = 0; j < len / 2; j++) {
                double u = real[i + j], v = real[i + j + len / 2] * wCos + imag[i + j + len / 2] * wSin;
                real[i + j] = u + v;
                real[i + j + len / 2] = u - v;
                double tempW = wCos * wlenCos - wSin * wlenSin;
                wSin = wSin * wlenCos + wCos * wlenSin;
                wCos = tempW;
            }
        }
    }
    if (invert) {
        for (int i = 0; i < n; i++) {
            real[i] /= n;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<long long> v(10, 0);
    for (int i = 0; i < k; i++) {
        int x;
        cin >> x;
        v[x] = 1;
    }
    vector<long long> comb = {1};
    int powerCount = n / 2;
    const long long mod = 998244353;
    while (powerCount > 0) {
        if (powerCount & 1) {
            comb = polynomialMultiply(comb, v, mod);
        }
        v = polynomialMultiply(v, v, mod);
        powerCount >>= 1;
    }
    long long totalSum = 0;
    for (auto val : comb) {
        totalSum = (totalSum + val * val) % mod;
    }
    cout << totalSum << "\n";
    return 0;
}

